manifest=dict(schemaVersion=1,sceneKey='Apartment',sourceScene=None,sourceBundleSha256=sha,sourceEvidence=source,scope='Finite original dropped-key F interaction through original Player Action controller and original end AnimationEvent, placed as an explicit reconstruction Apartment fixture; neutral player state only; no complete game equivalence.',noneActionId=-1,noneCanMove=True,actions=[action],targets=[key])
